using System.Text.Json.Serialization;
using Saldo360.Api.Authentication;
using Saldo360.Application.Debts;
using Saldo360.Domain.Common;
using Saldo360.Domain.Debts;
namespace Saldo360.Api.Debts;
public static class FinancialDebtEndpoints
{
 public static IEndpointRouteBuilder MapFinancialDebtEndpoints(this IEndpointRouteBuilder app){var g=app.MapGroup("/api/financial-workspaces/{workspaceId:guid}/debts").RequireAuthorization();g.MapGet("/",List);g.MapPost("/",Create).AddEndpointFilter<ValidateCsrfTokenFilter>();g.MapGet("/{id:guid}",Get);g.MapPut("/{id:guid}",Update).AddEndpointFilter<ValidateCsrfTokenFilter>();g.MapPost("/{id:guid}/suspend",Suspend).AddEndpointFilter<ValidateCsrfTokenFilter>();g.MapPost("/{id:guid}/resume",Resume).AddEndpointFilter<ValidateCsrfTokenFilter>();g.MapPost("/{id:guid}/settle",Settle).AddEndpointFilter<ValidateCsrfTokenFilter>();g.MapDelete("/{id:guid}",Archive).AddEndpointFilter<ValidateCsrfTokenFilter>();return app;}
 private static async Task<IResult> List(Guid workspaceId,bool? includeArchived,CurrentUser u,FinancialDebtService s,CancellationToken ct)=>await u.GetUserIdAsync(ct) is not{ } uid?Results.Unauthorized():await s.ListAsync(workspaceId,uid,includeArchived??false,ct) is var r&&!r.NotFound?Results.Ok(r.Items!.Select(DebtResponse.From)):Results.NotFound();
 private static async Task<IResult> Get(Guid workspaceId,Guid id,CurrentUser u,FinancialDebtService s,CancellationToken ct)=>await u.GetUserIdAsync(ct) is not{ } uid?Results.Unauthorized():await s.GetAsync(workspaceId,id,uid,ct) is{ } d?Results.Ok(DebtResponse.From(d)):Results.NotFound();
 private static async Task<IResult> Create(Guid workspaceId,DebtRequest? x,CurrentUser u,FinancialDebtService s,CancellationToken ct){if(await u.GetUserIdAsync(ct) is not{ } uid)return Results.Unauthorized();return Result(await s.CreateAsync(workspaceId,uid,x?.ToInput()??new(null,null,null,null,null,null,null,null,null,null,null,null,null,null,null,null,null),ct),d=>Results.Created($"/api/financial-workspaces/{workspaceId}/debts/{d.Id}",DebtResponse.From(d)));}
 private static async Task<IResult> Update(Guid workspaceId,Guid id,DebtRequest? x,CurrentUser u,FinancialDebtService s,CancellationToken ct){if(await u.GetUserIdAsync(ct) is not{ } uid)return Results.Unauthorized();return Result(await s.UpdateAsync(workspaceId,id,uid,x?.ToInput()??new(null,null,null,null,null,null,null,null,null,null,null,null,null,null,null,null,null),ct),d=>Results.Ok(DebtResponse.From(d)));}
 private static Task<IResult> Suspend(Guid workspaceId,Guid id,CurrentUser u,FinancialDebtService s,CancellationToken ct)=>Change(workspaceId,id,u,s,"suspend",ct);
 private static Task<IResult> Resume(Guid workspaceId,Guid id,CurrentUser u,FinancialDebtService s,CancellationToken ct)=>Change(workspaceId,id,u,s,"resume",ct);
 private static Task<IResult> Settle(Guid workspaceId,Guid id,CurrentUser u,FinancialDebtService s,CancellationToken ct)=>Change(workspaceId,id,u,s,"settle",ct);
 private static Task<IResult> Archive(Guid workspaceId,Guid id,CurrentUser u,FinancialDebtService s,CancellationToken ct)=>Change(workspaceId,id,u,s,"archive",ct);
 private static async Task<IResult> Change(Guid f,Guid id,CurrentUser u,FinancialDebtService s,string op,CancellationToken ct){if(await u.GetUserIdAsync(ct) is not{ } uid)return Results.Unauthorized();return Result(await s.ChangeAsync(f,id,uid,op,ct),d=>Results.Ok(DebtResponse.From(d)));}
 private static IResult Result(DebtResult r,Func<DebtDto,IResult> ok)=>r.Access switch{DebtAccess.NotFound=>Results.NotFound(),DebtAccess.Invalid=>Results.ValidationProblem(r.Errors!),DebtAccess.Conflict=>Results.Conflict(new{title=r.Message}),_=>ok(r.Debt!)};
}
[JsonUnmappedMemberHandling(JsonUnmappedMemberHandling.Disallow)]
public sealed record DebtRequest(string? Name,string? Description,string? DebtType,string? LenderName,Guid? ResponsibleAccountId,string? OriginalPrincipal,string? OutstandingPrincipal,string? OutstandingBalance,DateOnly? BalanceReferenceDate,DateOnly? ContractDate,DateOnly? FirstDueDate,int? InstallmentCount,int? PaidInstallmentCount,string? InstallmentAmount,string? InterestRate,string? InterestRatePeriod,string? AmortizationMethod){public DebtInput ToInput()=>new(Name,Description,DebtType,LenderName,ResponsibleAccountId,OriginalPrincipal,OutstandingPrincipal,OutstandingBalance,BalanceReferenceDate,ContractDate,FirstDueDate,InstallmentCount,PaidInstallmentCount,InstallmentAmount,InterestRate,InterestRatePeriod,AmortizationMethod);}
public sealed record DebtResponse(Guid Id,Guid WorkspaceId,string Name,string? Description,string DebtType,string? LenderName,Guid? ResponsibleAccountId,string OriginalPrincipal,string? OutstandingPrincipal,string? OutstandingBalance,DateOnly? BalanceReferenceDate,DateOnly ContractDate,DateOnly? FirstDueDate,int? InstallmentCount,int? PaidInstallmentCount,string? InstallmentAmount,string? InterestRate,string? InterestRatePeriod,string? AmortizationMethod,string Status,string Currency,DateTimeOffset CreatedAt,DateTimeOffset UpdatedAt,DateTimeOffset? ArchivedAt){public static DebtResponse From(DebtDto x)=>new(x.Id,x.WorkspaceId,x.Name,x.Description,x.DebtType.ToString(),x.LenderName,x.ResponsibleAccountId,Money.Format(x.OriginalPrincipal),x.OutstandingPrincipal is{} op?Money.Format(op):null,x.OutstandingBalance is{} ob?Money.Format(ob):null,x.BalanceReferenceDate,x.ContractDate,x.FirstDueDate,x.InstallmentCount,x.PaidInstallmentCount,x.InstallmentAmount is{} ia?Money.Format(ia):null,x.InterestRate is{} rate?Money.Format(rate):null,x.InterestRatePeriod?.ToString(),x.AmortizationMethod?.ToString(),x.Status.ToString(),x.Currency,x.CreatedAt,x.UpdatedAt,x.ArchivedAt);}
